-- ----------------------------
-- Table structure for activity
-- ----------------------------
DROP TABLE IF EXISTS `activity`;
CREATE TABLE `activity`  (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '活动ID(支持数字ID和UUID)',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '标题',
  `type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '展演/展览/培训/比赛',
  `start_time` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `location` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '地点',
  `description` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '描述',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0草稿 1报名中 2进行中 3已结束',
  `cover_file_id` bigint NULL DEFAULT NULL COMMENT '封面文件ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_status_start`(`status` ASC, `start_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '活动' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of activity
-- ----------------------------
INSERT INTO `activity` VALUES ('ACT-2025-001', '「古蜀谜踪」三星堆主题沉浸式剧本杀', '体验', '2025-11-01 09:00:00', '2025-11-01 12:00:00', '四川省成都市锦江区沉浸式剧本推理馆', '以三星堆青铜神树、黄金面具等文物为线索，打造沉浸式古蜀文明剧本杀。参与者将化身古蜀部落的不同角色，通过破解谜题、还原剧情，揭开古蜀文明的神秘面纱。活动融合了三星堆文物知识科普与推理互动，让你在烧脑剧情中，沉浸式了解古蜀祭祀、图腾文化与青铜文明，适合朋友、同学组队参与。', 1, 161, '2025-10-10 10:00:00', '2026-05-06 18:39:17');
INSERT INTO `activity` VALUES ('ACT-2025-002', '「小小考古家」三星堆青铜文化亲子研学营', '培训', '2025-10-15 08:00:00', '2025-10-25 18:00:00', '四川省德阳市三星堆考古遗址公园研学基地', '专为亲子家庭打造的三星堆主题研学活动，通过互动体验与趣味课程，让孩子了解古蜀文明。活动包含：① 三星堆博物馆专业讲解，认识青铜大立人、神树、黄金面具等文物；② 模拟考古挖掘体验，亲手 “发掘” 迷你青铜文物模型；③ 青铜器 DIY 上色，复刻青铜面具、神鸟造型；④ 亲子协作完成 “古蜀文明手抄报”，记录研学收获。活动兼顾知识性与趣味性，让孩子在实践中感受传统文化的魅力，增进亲子互动。', 2, 162, '2025-09-20 14:30:00', '2026-05-06 18:42:38');
INSERT INTO `activity` VALUES ('ACT-2025-003', '三星堆古蜀纹样服饰刺绣体验课', '体验', '2025-09-10 19:00:00', '2025-09-10 21:00:00', '四川省成都市锦江区蜀绣博物馆体验工坊', '本次课程将三星堆文物纹样与传统刺绣技艺结合，带你亲手制作古蜀主题刺绣作品。活动包含：① 三星堆青铜纹饰（回纹、云纹、兽面纹）文化解读；② 基础刺绣针法教学（平针、套针、盘金绣）；③ 以三星堆面具、神鸟纹样为图案，完成刺绣书签 / 杯垫作品；④ 非遗绣娘现场指导，零基础也能轻松上手。成品可带走作为纪念，在一针一线中感受古蜀纹样与传统刺绣的双重魅力。', 3, 163, '2025-08-25 10:00:00', '2026-05-06 18:44:08');
INSERT INTO `activity` VALUES ('ACT-2025-004', '三星堆青铜面具拓印非遗体验工坊', '体验', '2025-12-05 08:00:00', '2025-12-05 17:00:00', '四川省成都市三星堆博物馆公众教育区', '本次工坊带你走进 “拓印” 这一古老技艺，以三星堆青铜面具为原型，亲手复刻文物纹样。活动包含：① 拓印历史与三星堆文物纹样导赏；② 拓印工具使用教学（宣纸、拓包、墨汁的使用技巧）；③ 青铜面具拓印实操，零基础也能完成专属拓印作品；④ 作品装裱与文化解读，将千年古蜀符号定格在纸上。成品可带走作为纪念，让你近距离感受文物纹路的魅力。', 1, 160, '2025-10-12 15:00:00', '2026-05-06 18:31:02');
INSERT INTO `activity` VALUES ('ACT-2025-005', '三星堆古蜀文明非遗手作体验课', '体验', '2025-11-15 13:00:00', '2025-11-15 17:30:00', '四川省成都市三星堆博物馆文创体验中心', '本次研学营以三星堆青铜文明为核心，打造沉浸式考古体验与文化学习课程。课程包含：① 三星堆遗址考古现场云讲解，了解青铜大立人、神树等文物的发掘故事；② 青铜器铸造工艺科普，学习范铸法与古蜀冶金技术；③ 模拟考古挖掘体验，亲手 “发掘” 迷你青铜文物模型；④ 文创产品开发实践，以三星堆元素为主题设计专属文创草图。活动配备专业研学导师，兼顾知识性与趣味性，适合亲子家庭、学生群体参与，在实践中感受古蜀文明的辉煌。', 1, 158, '2025-10-13 09:30:00', '2026-05-06 18:26:25');
INSERT INTO `activity` VALUES ('ACT-2025-006', '三星堆青铜文化研学与考古体验营', '体验', '2025-11-20 09:00:00', '2025-11-22 18:00:00', '四川省德阳市三星堆考古遗址公园研学基地', '本次研学营以三星堆青铜文明为核心，打造沉浸式考古体验与文化学习课程。课程包含：① 三星堆遗址考古现场云讲解，了解青铜大立人、神树等文物的发掘故事；② 青铜器铸造工艺科普，学习范铸法与古蜀冶金技术；③ 模拟考古挖掘体验，亲手 “发掘” 迷你青铜文物模型；④ 文创产品开发实践，以三星堆元素为主题设计专属文创草图。活动配备专业研学导师，兼顾知识性与趣味性，适合亲子家庭、学生群体参与，在实践中感受古蜀文明的辉煌。', 1, 159, '2025-10-14 11:00:00', '2026-05-06 18:29:10');

-- ----------------------------
-- Table structure for activity_signup
-- ----------------------------
DROP TABLE IF EXISTS `activity_signup`;
CREATE TABLE `activity_signup`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `activity_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '活动ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0待审 1通过 2拒绝 3已签到',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_activity_user`(`activity_id` ASC, `user_id` ASC) USING BTREE,
  INDEX `idx_user`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '活动报名' ROW_FORMAT = DYNAMIC;

