-- ----------------------------
-- Table structure for course
-- ----------------------------
DROP TABLE IF EXISTS `course`;
CREATE TABLE `course`  (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '课程ID(支持数字ID和UUID)',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '标题',
  `level` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '难度等级',
  `description` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '描述',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态',
  `cover_file_id` bigint NULL DEFAULT NULL COMMENT '封面文件ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '课程' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of course
-- ----------------------------
INSERT INTO `course` VALUES ('CRS-2025-001', '三星堆学术探源——古蜀文明的深层解读', 'advanced', '面向有一定历史、考古基础的学习者，深入探讨三星堆文明的起源、发展、衰落的学术争议与研究成果。结合多学科视角（考古学、人类学、艺术学），分析古蜀社会结构、宗教信仰、族群构成，解读三星堆文明在中华文明探源工程中的重要地位，适合历史专业学生、考古爱好者、文化研究者。', 1, 118, '2025-09-01 10:00:00', '2025-09-01 10:00:00');
INSERT INTO `course` VALUES ('CRS-2025-002', '三星堆趣味课——动手解锁古蜀文明', 'elementary', '以“趣味体验+知识传递”为核心，结合文物拼图、模拟考古、工艺复刻等互动形式，让学习者在动手过程中了解三星堆文物的造型、工艺与文化内涵。兼顾趣味性与知识性，避开晦涩的学术表述，适合青少年、家庭群体，以及喜欢动手体验的三星堆爱好者，让古蜀文明变得可触可感。', 1, 117, '2025-09-10 14:00:00', '2025-09-10 14:00:00');
INSERT INTO `course` VALUES ('CRS-2025-003', '三星堆考古记——从发掘现场到文明解码', 'intermediate', '以三星堆考古历程为线索，还原每一次重大发掘的细节，讲解考古工作者如何运用科技手段破解古蜀谜题。从传统考古发掘到同位素分析、DNA检测等现代技术的应用，从祭祀坑的性质争议到文物修复的艰辛，带大家走进考古现场，了解古蜀文明的探索过程，适合对考古学感兴趣、想了解“如何发现古蜀”的人群。', 1, 116, '2025-09-15 16:30:00', '2025-09-15 16:30:00');
INSERT INTO `course` VALUES ('CRS-2025-005', '三星堆文物密码——青铜与黄金里的古蜀信仰', 'intermediate', '聚焦三星堆最具代表性的文物，跳出“外观猎奇”，深入解读每一件文物的工艺、象征意义与背后的古蜀信仰。从青铜神树的“通天”寓意到金杖的王权象征，从纵目面具的文化内涵到玉器的礼仪功能，结合考古研究成果，让文物“开口说话”，适合对三星堆文物有深入兴趣、想了解文化内核的爱好者。', 1, 115, '2025-09-20 10:30:00', '2025-09-20 10:30:00');
INSERT INTO `course` VALUES ('CRS-2025-006', '三星堆文化传承——从考古发现到当代活化', 'intermediate', '聚焦三星堆文化的当代价值与传承发展，讲解三星堆文物的保护技术、文化IP的打造、科普传播的实践。从三星堆博物馆的展览设计到文创产品的开发，从科普活动的开展到文化自信的培育，了解古蜀文明如何在当代“活”起来，适合关注文化传承、文创设计、科普传播的人群。', 1, 131, '2025-09-25 15:00:00', '2026-05-06 16:13:25');

-- ----------------------------
-- Table structure for course_chapter
-- ----------------------------
DROP TABLE IF EXISTS `course_chapter`;
CREATE TABLE `course_chapter`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `course_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '课程ID',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '章节标题',
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '内容',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_course_sort`(`course_id` ASC, `sort` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 30 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '课程章节' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of course_chapter
-- ----------------------------
INSERT INTO `course_chapter` VALUES (1, 'CRS-2025-001', '第一章：三星堆文明的起源争议与研究', '本章深入探讨三星堆文明的起源争议，介绍夏代移民南迁说、本土发展说的学术争论，结合地层年代、文物特征等考古证据，以及人类学、环境学的多学科视角解读起源问题。', 1);
INSERT INTO `course_chapter` VALUES (2, 'CRS-2025-001', '第二章：古蜀社会与宗教信仰体系', '本章分析古蜀社会结构与宗教信仰体系，从文物视角解读古蜀王国的王权与神权关系，阐述太阳崇拜、祖先崇拜等人神互通的核心信仰，推测祭祀坑功能与祭祀仪式。', 2);
INSERT INTO `course_chapter` VALUES (3, 'CRS-2025-001', '第三章：三星堆与中华文明探源', '本章解读三星堆在中华文明探源工程中的重要地位，探讨其对填补中华文明起源空白的作用，分析三星堆文明独特性与多元一体的学术争议，介绍最新考古研究成果。', 3);
INSERT INTO `course_chapter` VALUES (9, 'CRS-2025-002', '第一章：黄金面具是怎样制作的？', '暂无', 1);
INSERT INTO `course_chapter` VALUES (10, 'CRS-2025-002', '第二章：模拟考古体验——感受考古乐趣', '暂无', 2);
INSERT INTO `course_chapter` VALUES (11, 'CRS-2025-002', '第三章：简易工艺复刻——读懂古蜀智慧', '本章通过简易工艺复刻活动，让学习者模拟金杖金箔包裹工艺、临摹青铜经典纹饰，在动手过程中读懂古蜀智慧，并通过成果分享巩固所学知识。', 3);
INSERT INTO `course_chapter` VALUES (15, 'CRS-2025-003', '第一章：考古溯源——三星堆的百年发掘之路', '  本章追溯三星堆的百年发掘之路，依次介绍1929年的偶然发现、1934年的早期发掘、1986年一、二号祭祀坑的震惊发现，以及近年来三至八号祭祀坑的新突破。', 1);
INSERT INTO `course_chapter` VALUES (16, 'CRS-2025-003', '第二章：考古现场——技术与耐心的结合', '  本章带大家走进考古现场，讲解考古发掘的完整流程，介绍同位素分析、DNA检测等科技考古手段的应用，以及青铜、黄金等出土文物的应急保护与修复技术。', 2);
INSERT INTO `course_chapter` VALUES (17, 'CRS-2025-003', '第三章：考古谜题——未被破解的古蜀密码', '  本章探讨三星堆未被破解的考古谜题，包括祭祀坑的祭祀性质与宗庙被毁原因、三星堆未发现确切文字的谜团，以及三星堆文明衰落的原因及其与金沙文明的关系。', 3);
INSERT INTO `course_chapter` VALUES (20, 'CRS-2025-005', '第一章：青铜之巅——古蜀青铜工艺与信仰表达', '  本章解读古蜀青铜工艺与信仰表达，涵盖青铜神树的“通天”寓意、纵目面具的文化内涵、青铜大立人的身份之谜，以及分段铸造法所体现的古蜀青铜技术水平。', 1);
INSERT INTO `course_chapter` VALUES (21, 'CRS-2025-005', '第二章：黄金之光——权力与祭祀的物质载体', '  本章聚焦三星堆黄金器物，解密金杖的制作工艺与文化关联、金面具的复原过程与祭祀功能，探讨古蜀黄金工艺的独特性及其与周边文明的交流痕迹。', 2);
INSERT INTO `course_chapter` VALUES (22, 'CRS-2025-005', '第三章：玉石礼器——古蜀的礼仪与宇宙观', '  本章分析三星堆玉石礼器的文化意义，介绍玉璋、玉戈等礼器对中原夏文化的吸收，解读玉器纹饰隐藏的古蜀宇宙观与祖先崇拜，推测祭祀坑中大量象牙的来源与用途。', 3);
INSERT INTO `course_chapter` VALUES (24, 'CRS-2025-006', '第一章：三星堆文物的保护与修复', '  本章聚焦三星堆文物的保护与修复，介绍文物的保存困境与对应保护措施，讲解青铜、黄金、玉器等文物的现代化修复工艺，以及文物保护与修复陈列的影响力。', 1);
INSERT INTO `course_chapter` VALUES (25, 'CRS-2025-006', '第二章：三星堆文化的当代传播', '  本章阐述三星堆文化的当代传播，介绍“跟着总书记学历史”等科普实践的影响，讲解纪录片、短视频、展览等媒体传播形式，以及三星堆文化的海外传播与国际认知。', 2);
INSERT INTO `course_chapter` VALUES (26, 'CRS-2025-006', '第三章：三星堆文化的活化与创新', '  本章探讨三星堆文化的活化与创新，解读文创产品的设计理念与特色，分析三星堆文化IP的构建与当代应用，挖掘古蜀文明的当代价值与青少年教育传承路径。', 3);

-- ----------------------------
-- Table structure for heritage_item
-- ----------------------------
DROP TABLE IF EXISTS `heritage_item`;
CREATE TABLE `heritage_item`  (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '作品ID(支持数字ID和UUID)',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '标题',
  `category` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '类别',
  `region` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '地区',
  `summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '摘要',
  `description` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '描述',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 0草稿 1待审 2已发布 3下架',
  `creator_id` bigint NULL DEFAULT NULL COMMENT '创建人',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_category_region_status`(`category` ASC, `region` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '非遗作品' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of heritage_item
-- ----------------------------
INSERT INTO `heritage_item` VALUES ('HI-2025-001', '祭山图玉边璋', '玉器', '四川广汉', '最早玉器线刻 “祭祀连环画”，完整记录古蜀山陵之祭。', '通长 54.2 厘米，墨玉质，两面阴刻对称图案：山陵、牙璋、云雷纹、跪坐人像。分上下两组，描绘古蜀人祭祀山川的完整仪式，是研究古蜀神权政治、祭祀礼仪、宇宙观的直接物证，为首批禁止出国（境）展览文物。', 2, 1, '2024-03-15 10:00:00', '2024-03-15 10:00:00', '2025-10-16 15:33:05');
INSERT INTO `heritage_item` VALUES ('HI-2025-002', '完整金面具', '金器', '四川广汉', '三星堆迄今最完整、最大型金面具，覆盖青铜人头像面部。', '宽 37.2 厘米，高 16.5 厘米，重约 100 克。锤揲成型，眉眼镂空，鼻梁高挺，面部线条刚劲。为高等级贵族 / 神巫专用，金面罩象征神性、高贵、不朽，体现古蜀对黄金的崇拜与冶金水平。', 2, 1, '2024-04-10 09:30:00', '2024-04-10 09:30:00', '2025-10-16 15:33:06');
INSERT INTO `heritage_item` VALUES ('HI-2025-003', '青铜纵目面具', '青铜器', '四川广汉', '三星堆标志性 “纵目” 神造像，眼球柱状外凸，造型极度夸张。', '宽 1.38 米，高 0.66 米，重 71.1 公斤。眼球呈圆柱状外凸 16 厘米，双耳如翼外展，鼻梁直挺，口裂深长露齿。对应《蜀王本纪》“蚕丛纵目” 的祖先神崇拜，是宗庙祭祀核心重器，强化神性与震慑力。', 2, 1, '2024-05-20 14:00:00', '2024-05-20 14:00:00', '2025-10-16 15:33:07');
INSERT INTO `heritage_item` VALUES ('HI-2025-004', '金杖', '金器', '四川广汉', '古蜀鱼凫王朝的权力象征，金箔包木杖，纹饰含巫师、鱼、鸟。', '长 143 厘米，金箔厚约 0.2 毫米，重 463 克。出土时木芯已朽，仅存金皮。一端刻有三组图案：对称巫师头像、鱼、鸟、箭纹。学界认为是鱼凫王朝的王权权杖 / 通神法器，体现古蜀与西亚、中原文化交融特征。', 2, 1, '2024-06-08 11:15:00', '2024-06-08 11:15:00', '2025-10-16 15:33:07');
INSERT INTO `heritage_item` VALUES ('HI-2025-005', '青铜大立人像', '青铜器', '四川广汉', '世界同时期最大青铜立人像，集王权、神权于一体的领袖造像。', '通高 2.62 米（人像高 180cm），重约 180 公斤。头戴高冠，身着多层龙纹礼衣，双手环握中空（原应持法器），赤足立于神兽台座。采用分段浇铸法嵌铸而成，是古蜀国蜀王兼大祭司的象征，代表神权与王权合一的最高权威。', 2, 1, '2024-07-12 08:45:00', '2024-07-12 08:45:00', '2025-10-16 15:33:08');
INSERT INTO `heritage_item` VALUES ('HI-2025-006', '青铜神树（一号神树）', '青铜器', '四川广汉', '中国现存最大单件青铜文物，象征古蜀宇宙观与通天神树，修复耗时近 10 年。', '通高 3.96 米，由底座、树身、神龙三部分组成。底座为三山相连，树身分三层九枝，每枝立一神鸟（共九鸟），一条巨龙沿树干蜿蜒而下。采用分段铸造、铆接、嵌铸复合工艺，出土时破碎为数百片，1986—1996 年修复完成。代表古蜀人 “天地相通、人神共居” 的宇宙观，对应神话中的扶桑、建木。', 2, 1, '2025-10-16 15:33:25', '2024-08-20 10:30:00', '2025-10-16 15:33:09');

