-- ----------------------------
-- Table structure for inheritor
-- ----------------------------
DROP TABLE IF EXISTS `inheritor`;
CREATE TABLE `inheritor`  (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '传承人ID(支持数字ID和UUID)',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '姓名',
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '称号',
  `region` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '地区',
  `bio` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '简介',
  `avatar_file_id` bigint NULL DEFAULT NULL COMMENT '头像文件',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_region_name`(`region` ASC, `name` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '传承人' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of inheritor
-- ----------------------------
INSERT INTO `inheritor` VALUES ('85a91790-2876-44fe-90d2-5a088f97bc57', '马燕如', '中国国家博物馆研究馆员、金器保护修复专家', '北京市', '马燕如主持完成了三星堆遗址 3、5 号坑金面罩（含完整金面具）的保护修复工作，她创新采用三维建模、3D 打印辅助矫形等数字技术，成功修复了这面中国商周时期尺寸最大、最厚重的金面具，破解了金面罩变形矫正与工艺复原的难题，是三星堆金器保护与研究的核心专家。', 130, '2026-05-06 16:05:02', '2026-05-06 16:05:02');
INSERT INTO `inheritor` VALUES ('f71bde4a-fb05-4590-b503-36c7f37d711f', '杨晓邬', '四川省文物考古研究院副研究馆员、三星堆文物修复奠基人', '四川省德阳市广汉市', '杨晓邬是三星堆文物修复的开创者与奠基人，1987 年起主持三星堆祭祀坑出土文物的修复工作，完成了青铜神树、青铜大面具、玉边璋、金杖等国宝级文物的修复。他出身清宫造办处古铜局修复世家，将传统技艺与现代修复理念结合，带出郭汉中等优秀徒弟，奠定了三星堆文物修复的技术体系，是古蜀青铜修复技艺的源头传承者。', 129, '2026-05-06 15:59:35', '2026-05-06 15:59:35');
INSERT INTO `inheritor` VALUES ('INH-2025-003', '朱章义', '成都金沙遗址博物馆原馆长、研究馆员', '四川省成都市', '朱章义亲身参与三星堆、金沙遗址两大古蜀文明核心考古发掘，是连接三星堆与金沙文明的关键学者。主持考古研究、博物馆建设与文化传播，推动古蜀文明 “多元一体” 定位研究，培养青年考古与文博人才，为古蜀文明传承提供坚实学术支撑。', 128, '2023-05-20 14:00:00', '2024-09-10 16:45:00');
INSERT INTO `inheritor` VALUES ('INH-2025-004', '朱亚蓉', '三星堆博物馆陈列保管部副部长、文物修复高级技师', '四川省德阳市广汉市', '朱亚蓉深耕三星堆29 年，全程参与博物馆建设、文物保护、展陈策划与国际传播。主导三星堆新馆陈列、开放式文物修复馆，推动数字化展示与全球巡展，让古蜀文明走进大众、走向世界，是古蜀文明活化利用与传播传承的核心人物。', 127, '2023-07-08 11:15:00', '2024-10-05 10:00:00');
INSERT INTO `inheritor` VALUES ('INH-2025-005', '郭汉中', '三星堆博物馆陈列保管部副部长、文物修复高级技师', '四川省德阳市广汉市', '郭汉中从事文物修复工作40 余年，亲手修复三星堆青铜神树、青铜大立人、黄金面具等珍贵文物 6000 余件，是古蜀青铜文物修复技艺的代表性传承人。他创新 “蜡模固型” 等技术，解决象牙与青铜器修复难题，并通过师徒传承、大师工作室培养新一代文物修复人才，以匠心守护古蜀文明。', 126, '2023-09-12 08:45:00', '2024-11-20 14:30:00');

