-- ----------------------------
-- Table structure for quiz_record
-- ----------------------------
DROP TABLE IF EXISTS `quiz_record`;
CREATE TABLE `quiz_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `score` int NOT NULL COMMENT '得分',
  `total_time` int NOT NULL COMMENT '总用时(秒)',
  `correct_count` int NOT NULL COMMENT '答对题数',
  `total_count` int NOT NULL COMMENT '总题数',
  `mode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'challenge' COMMENT '答题模式: challenge-挑战模式, practice-练习模式',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ranking`(`score` DESC, `total_time` ASC) USING BTREE COMMENT '排行榜索引',
  INDEX `idx_user`(`user_id` ASC) USING BTREE COMMENT '用户索引'
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '答题记录表' ROW_FORMAT = Dynamic;

