INSERT INTO `shop_order_item` VALUES (11, 11, 'SP2025002', 'SP2025002', '三星堆古蜀文明金属书签套装', '复刻青铜文物神韵，藏千年古蜀浪漫于书页之间', 89.00, 2, 178.00);

-- ----------------------------
-- Table structure for shop_product
-- ----------------------------
DROP TABLE IF EXISTS `shop_product`;
CREATE TABLE `shop_product`  (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '商品ID(支持数字ID和UUID)',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '商品标题',
  `subtitle` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '副标题',
  `category_id` bigint NOT NULL COMMENT '类目ID',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '商品价格',
  `stock` int NOT NULL DEFAULT 0 COMMENT '库存数量',
  `detail` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '详情',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '0下架 1上架',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_category_status`(`category_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '商品SPU' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of shop_product
-- ----------------------------
INSERT INTO `shop_product` VALUES ('SP2025001', '三星堆青铜人面具文创香薰蜡烛', '复刻古蜀青铜神面，融香氛与非遗美学于一体', 7, 198.00, 45, '<h3>产品介绍</h3>\n<p>这款香薰以三星堆标志性的青铜人面具为设计原型，将古蜀文明的神秘美学与现代香氛生活巧妙融合。上半部分采用德化白瓷复刻青铜面具的标志性轮廓与细节，眉眼、耳廓的纹路高度还原文物神韵，点亮蜡烛时，暖光透过陶瓷缝隙晕染开来，仿佛重现古蜀神坛的神秘光晕；下半部分以青釉渐变瓷座呼应三星堆青铜的青绿色调，釉面温润有光泽，兼具装饰性与实用性。点燃蜡烛后，柔和的香气与暖调光影交织，为日常空间注入古蜀文明的静谧氛围感，既是一款治愈的香薰，也是一件可长久摆放的文创摆件。</p>\n<h3>工艺特点</h3>\n<ul>\n<li>非遗陶瓷工艺：主体采用德化白瓷与高温青釉工艺烧制，白瓷细腻温润，青釉渐变自然，釉面光滑无瑕疵，还原文物质感的同时，保证陶瓷容器的耐用性与安全性。</li><li>文物细节复刻：以三星堆青铜人面具为原型，手工修模复刻眉眼、耳廓的标志性纹路，线条流畅立体，高度还原古蜀文物的神秘气质。</li><li>天然香氛蜡质：采用大豆蜡与天然植物精油配方，燃烧稳定无烟，气味柔和不刺鼻，多款香型可选，适配不同场景的氛围需求。</li><li>双段式可拆卸设计：面具香薰杯与青釉底座可分离，蜡烛燃尽后，陶瓷杯可作为收纳罐、小花瓶重复使用，延长产品生命周期。</li>\n</ul>\n<h3>规格参数</h3><p>产品材质	德化白瓷、高温青釉陶瓷、大豆蜡、天然植物精油\n</p><p>产品尺寸	整体高约 12cm，直径约 8cm；上半面具杯高约 7cm，底座高约 5cm\n</p><p>蜡质容量	约 120g\n</p><p>燃烧时长	约 25-30 小时（视燃烧环境而定）\n</p><p>可选香型	古蜀秘境（木质调）、金沙桂雨（花香调）、青铜遗韵（东方调）\n</p><p>包装配件	文创礼盒、专用灭烛钩、产品说明书\n</p><p>适用场景	家居装饰、桌面摆件、伴手礼、博物馆文创收藏</p>', 1, '2025-10-15 11:30:12', '2025-10-15 11:30:12');
INSERT INTO `shop_product` VALUES ('SP2025002', '三星堆古蜀文明金属书签套装', '复刻青铜文物神韵，藏千年古蜀浪漫于书页之间', 11, 89.00, 17, '<h3><b style=\"\">产品介绍</b></h3>\n<p>&nbsp; &nbsp; &nbsp;这套金属书签以三星堆五大标志性文物为设计原型，将古蜀文明的神秘符号与现代阅读美学巧妙融合，打造兼具收藏与实用价值的文创单品。套装包含青铜大立人、神树、戴冠纵目面具、神鸟、青铜人首鸟身像五款主题书签，每款都精准复刻文物的核心特征，从立人的华服纹路到神树的枝叶细节，从面具的纵目轮廓到神鸟的羽翼线条，都通过金属雕刻工艺完美呈现。书签采用亮面镀金工艺，搭配非遗珐琅彩上色，色彩温润细腻，兼具金属的质感与古蜀文物的厚重感。夹在书页间，仿佛让千年古蜀文明与文字阅读产生奇妙联结，既是阅读时的实用标记，也是值得收藏的文化信物，更是送朋友、送同学的特色伴手礼。</p>\n<h3>工艺特点</h3>\n<ul>\n<li>文物细节复刻：以三星堆出土文物为原型，采用高精度蚀刻工艺，1:1 还原文物的纹路、轮廓与标志性特征，每一处细节都精准呈现古蜀文明的艺术魅力。</li><li>珐琅彩非遗工艺：书签图案采用高温珐琅彩上色，色彩饱满持久，不易掉色，复刻文物的青金配色，还原青铜文物的厚重质感与神秘氛围。</li><li>优质金属材质：主体采用黄铜镀真金工艺，表面光滑不易氧化，边缘打磨圆润无毛刺，长期使用仍能保持金属光泽，耐用性强。</li><li>轻量化设计：整体采用薄款金属片设计，厚度仅 0.3mm，不会损伤书页，夹取轻便，不影响阅读体验。</li>\n</ul>\n<h3>规格参数</h3><p>产品材质	黄铜镀真金、高温珐琅彩\n</p><p>产品尺寸	单枚书签高约 12cm，宽约 3cm（不同款式略有差异），厚度 0.3mm\n</p><p>套装配置	5 枚主题书签（青铜大立人 / 神树 / 戴冠纵目面具 / 神鸟 / 人首鸟身像）+ 文创礼盒 + 产品说明卡\n</p><p>工艺细节	蚀刻雕刻、珐琅填色、镀金防氧化处理\n</p><p>适用场景	阅读标记、学生文具、文创收藏、伴手礼、博物馆周边礼品\n</p><p>保养说明	避免接触酸碱液体，存放于干燥处，氧化时可用软布轻轻擦拭</p>', 1, '2025-10-15 11:30:12', '2025-10-15 11:30:12');
INSERT INTO `shop_product` VALUES ('SP2025003', '三星堆古蜀文明主题迷你象棋套装', '复刻青铜文物形象，以棋为媒解锁古蜀文明', 11, 299.00, 100, '<h3>产品介绍</h3>\n<p>&nbsp; &nbsp; &nbsp; 这套迷你象棋以三星堆标志性文物为设计灵感，将中国传统象棋与古蜀文明元素巧妙融合，打造兼具收藏性、趣味性与文化性的特色文创产品。棋子造型全部源自三星堆出土文物，红方采用鎏金质感，复刻黄金面具、太阳神鸟等金色文物形象；黑方采用仿青铜绿配色，还原青铜大立人、纵目面具、神坛等经典文物轮廓，每一枚棋子都对应象棋中的 “将 / 帅、士、象、马、车、炮、卒”，通过文物形象传递古蜀文明的神秘与厚重。棋子底部自带印章功能，印面雕刻对应棋子名称，既是可以对弈的象棋，也是一套可用于手账、书信的迷你印章；搭配实木底座与收纳礼盒，无论是作为桌面摆件、趣味对弈工具，还是作为特色伴手礼，都能传递独特的古蜀文化魅力。</p>\n<h3>工艺特点</h3>\n<ul>\n<li>文物 IP 创意融合：以三星堆七大核心文物为原型，为每一枚棋子赋予专属古蜀形象，将象棋规则与文物故事结合，每一局对弈都是一次古蜀文明的趣味科普。</li><li>双色质感工艺：红方棋子采用镀金工艺，还原金器的华贵光泽；黑方采用仿青铜做旧工艺，复刻青铜器的青绿色泽与厚重质感，双色对比鲜明，还原古蜀金器与青铜器并存的文化特征。</li><li>立体雕刻细节：采用高精度 3D 开模工艺，棋子造型立体饱满，从面具的眉眼、立人的华服到神鸟的羽翼，都做了细节化雕刻，纹路清晰精致，兼具把玩与观赏价值。</li><li>印章与象棋双功能：棋子底部自带印面雕刻，搭配印泥即可作为印章使用，实现 “一棋两用”，兼顾对弈、收藏与手账装饰多重用途。</li>\n</ul>\n<h3>规格参数</h3><p>产品材质	合金镀色（仿金 / 仿青铜）、实木底座\r</p><p>棋子规格	单枚棋子高约 3-4cm，底座直径约 2cm，共 32 枚标准象棋棋子\r</p><p>套装配置	32 枚三星堆主题棋子、仿实木收纳底座、棋盘布、产品说明书\r</p><p>工艺细节	3D 立体雕刻、双色镀色工艺、底部印章雕刻、防氧化保护处理\r</p><p>适用场景	桌面摆件、趣味对弈、文创收藏、伴手礼、博物馆周边礼品\r</p><p>保养说明	避免接触酸碱液体与潮湿环境，氧化时可用软布轻轻擦拭，长期不使用可放入收纳盒保存</p>', 1, '2025-10-15 11:30:12', '2025-10-15 11:30:12');
INSERT INTO `shop_product` VALUES ('SP2025004', '三星堆「古蜀之光」系列盲盒手办', '解锁古蜀文明盲盒，集齐三星堆神秘天团', 3, 69.00, 29, '<h3>产品介绍</h3>\n<p>&nbsp; &nbsp; &nbsp; 这款「古蜀之光」系列盲盒，以三星堆出土文物为灵感，将青铜大立人、纵目面具、神树、神鸟等经典 IP 进行萌化再设计，打造出一套兼具趣味性与文化性的潮玩手办。系列包含 6 个常规款 + 1 个隐藏款，每一款都还原了文物的核心特征：青铜大立人手握金杖，纵目面具带着标志性的夸张大眼，神树款自带分层结构，神鸟款羽翼细节灵动。整体采用仿青铜绿与鎏金配色，还原文物质感的同时，加入了圆润可爱的 Q 版线条，打破了古蜀文物的厚重距离感。无论是拆盒收集、作为桌面摆件，还是送给喜欢潮玩与传统文化的朋友，都能带来 “解锁古蜀盲盒” 的惊喜体验，让千年文明以更年轻的方式走进日常。</p>\n<h3>工艺特点</h3>\n<ul>\n<li>文物 IP 萌化设计：以三星堆 7 大核心文物为原型，将威严的青铜形象转化为 Q 版潮玩，保留文物标志性特征的同时，加入拟人化动作与细节，兼顾文化还原与潮玩趣味性。</li><li>仿真质感工艺：主体采用 PVC 环保材质，表面做仿青铜绿做旧效果，搭配 ABS 电镀工艺打造的鎏金配件（面具、权杖、神鸟），还原文物的金属光泽与青釉质感。</li><li>高精度细节刻画：每一款手办都经过 3D 建模与多次修模，服饰纹路、面具纹样、配饰细节都清晰呈现，关节与配件贴合紧密，无毛刺、无溢色。</li><li>隐藏款惊喜设计：系列设置 1 款隐藏款特殊造型，采用特殊涂装工艺，配色与细节区别于常规款，增加收藏与拆盒的趣味性。</li>\n</ul>\n<h3>规格参数</h3><p>产品材质	PVC 环保树脂、ABS 电镀配件</p><p>单盒尺寸	约 10cm×10cm×15cm</p><p>手办高度	常规款约 8-10cm，隐藏款约 12cm</p><p>系列配置	6 个常规款 + 1 个隐藏款（概率 1/72）</p><p>工艺细节	3D 立体建模、仿青铜做旧涂装、电镀金配件、无毛刺修边</p><p>适用场景	桌面摆件、潮玩收藏、文创礼品、盲盒爱好者收集</p><p>保养说明	避免阳光直射与潮湿环境，电镀配件避免接触酸碱液体，脏污可用软布轻轻擦拭</p>', 1, '2025-10-15 11:30:12', '2025-10-15 11:30:12');
INSERT INTO `shop_product` VALUES ('SP2025005', '三星堆青铜大立人立体冰箱贴', '复刻古蜀青铜神韵，把千年文明贴在生活里', 8, 38.00, 24, '<h3>产品介绍</h3>\n<p>&nbsp; &nbsp; &nbsp; &nbsp;这款冰箱贴以三星堆标志性文物青铜大立人为原型，1:1 还原了立人的整体造型与细节纹路，是一款兼具装饰性与文化感的迷你文创单品。立人头戴高冠、身着华服，双手呈环握姿态，底座同样复刻了文物的兽面纹饰；表面采用仿青铜做旧工艺，还原了文物出土后的青绿色泽与历史质感，背面内置强磁，可牢固吸附在冰箱、白板、文件柜等金属表面。无论是作为冰箱装饰、留言固定器，还是作为随手礼送给朋友，都能把古蜀文明的神秘气质融入日常，成为家居里一抹独特的文化风景。</p>\n<h3>工艺特点</h3>\n<ul>\n<li>文物细节复刻：以三星堆青铜大立人为原型，采用立体开模工艺，还原文物的服饰纹路、面部轮廓与底座纹饰，每一处细节都清晰呈现，还原古蜀文物的艺术特征。</li><li>仿青铜做旧工艺：表面采用青绿色仿青铜涂装，做旧效果自然逼真，还原了青铜器的历史质感，不易掉色、不易氧化。</li><li>强磁吸附设计：背面内置隐藏式强磁铁，吸力强劲，可牢固吸附在各类金属表面，不易掉落，且不会刮伤冰箱表面。</li><li>轻量化一体成型：整体采用环保树脂材质，一体成型无拼接，手感细腻，边缘打磨圆润，无毛刺、无尖锐棱角，安全耐用。</li>\n</ul>\n<h3>规格参数</h3>\n<p>产品材质	环保树脂、强磁铁</p><p>产品尺寸	高约 8cm，底座宽约 2cm</p><p>工艺细节	3D 立体开模、仿青铜做旧涂装、强磁吸附、边缘圆润处理</p><p>适用场景	冰箱装饰、白板磁吸、留言固定、文创收藏、伴手礼</p><p>保养说明	避免摔落与高温暴晒，脏污可用软布轻轻擦拭，避免接触尖锐物品刮伤表面</p>', 1, '2025-10-15 11:30:12', '2025-10-15 11:30:12');
INSERT INTO `shop_product` VALUES ('SP2025006', '三星堆青铜神鸟毛绒公仔', '把千年青铜神鸟，揉成软 fufu 的治愈陪伴', 9, 78.00, 59, '<h3>产品介绍</h3>\n<p>&nbsp; &nbsp; 这款「啾啾鸟」毛绒公仔，以三星堆青铜神鸟为原型，将古蜀文明的神秘图腾，变成了软萌治愈的毛绒陪伴。它还原了文物标志性的青绿色调，把青铜神鸟的威严姿态，转化为圆滚滚的软萌造型：毛茸茸的身体搭配黑溜溜的圆眼睛，还有细细的小长腿，既保留了神鸟的辨识度，又充满了软乎乎的治愈感。公仔顶部还设计了挂绳孔，可搭配挂绳作为包挂、钥匙扣使用，也能直接放在桌面、床头当摆件，让千年古蜀的 “神鸟” 以最可爱的方式陪在身边。</p>\n<h3>工艺特点</h3>\n<ul>\n<li>文物 IP 萌化设计：以三星堆青铜神鸟为原型，提取文物的青绿色调与神鸟轮廓，将威严的青铜图腾转化为圆滚滚的毛绒形象，兼顾文化辨识度与软萌治愈感。</li><li>优质毛绒面料：采用高弹仿兔毛面料，手感柔软顺滑不掉毛，亲肤无刺激，久抱也不会变形，软乎乎的触感超治愈。</li><li>细节刺绣工艺：眼睛、羽毛纹路均采用精细刺绣工艺，线条平整牢固，不易脱线；鸟喙采用耐磨布料制作，还原神鸟的特征同时，兼顾把玩的耐用性。</li><li>多功能设计：公仔顶部自带挂绳孔，可搭配挂绳作为包挂、钥匙扣，也可直接作为桌面摆件、床头抱枕，满足不同场景的使用需求。</li>\n</ul>\n<h3>规格参数</h3>\n<p>产品材质	高弹仿兔毛面料、PP 棉填充、耐磨刺绣布料</p><p>产品尺寸	公仔本体直径约 10cm，含挂绳 / 腿高约 18cm</p><p>工艺细节	精细刺绣、高弹填充、锁边加固、挂绳孔设计</p><p>可选配件	配套挂绳（可作包挂 / 钥匙扣）</p><p>适用场景	桌面摆件、包挂装饰、床头抱枕、文创收藏、治愈系伴手礼</p><p>保养说明	可轻柔手洗，避免长时间暴晒，清洗后阴干即可，不可高温熨烫</p>', 1, '2025-10-15 11:30:12', '2025-10-15 11:30:12');
INSERT INTO `shop_product` VALUES ('SP2025007', '三星堆纵目青铜面具立体浮雕笔记本', '藏千年古蜀图腾，写进日常的神秘手账', 11, 39.00, 15, '<h3>产品介绍&nbsp; &nbsp;</h3>\n<p>&nbsp; &nbsp; &nbsp; &nbsp;这款笔记本以三星堆标志性的纵目青铜面具为核心设计，将古蜀文明的神秘图腾与手账文具巧妙融合，打造兼具收藏性与实用性的文创单品。封面采用藏青色仿皮材质，表面压印古蜀纹饰，搭配四角青铜纹金属护角，复刻古籍卷轴的复古质感；中央的立体浮雕面具，还原了青铜面具的眉眼、纹路与青金配色，凹凸质感强烈，摸起来充满历史厚重感。笔记本自带同色系皮质搭扣，可防止页面散开，内页采用米黄色护眼纸，兼顾书写流畅度与阅读舒适度，无论是日常记录、手账创作还是作为收藏款文创文具，都能让古蜀文明的神秘气质融入书写日常。</p>\n<h3>工艺特点</h3>\n<ul>\n<li>立体浮雕工艺：封面中央的青铜面具采用 3D 立体浮雕工艺，高度还原文物的轮廓、纹路与色彩层次，青金配色复刻青铜器的做旧质感，凹凸分明，极具视觉冲击力。</li><li>仿皮压纹封面：采用藏青色仿皮材质，表面压印古蜀图腾纹饰，搭配四角金属护角与侧边装饰件，复古质感拉满，耐磨防刮，不易变形。</li><li>优质内页纸张：内页采用 100g 米黄色护眼道林纸，书写顺滑不洇墨，适合钢笔、中性笔等多种笔具，长期保存不易泛黄。</li><li>细节设计加分：搭配同色系皮质搭扣，防止页面散开；书脊采用锁线装订，可平摊书写；内置书签带，方便快速定位页面，兼顾实用性与仪式感。</li>\n</ul>\n<h3>规格参数</h3>\n<p>产品材质	仿皮封面、金属浮雕面具、金属护角、米黄道林纸内页</p><p>产品尺寸	A5 规格（约 14.5cm×21cm），厚度约 2cm</p><p>内页配置	100g 米黄道林纸，共 128 张（256 页），横线内页</p><p>工艺细节	3D 立体浮雕、仿皮压纹、锁线装订、搭扣设计、金属护角</p><p>适用场景	日常记录、手账创作、学生文具、文创收藏、伴手礼</p><p>保养说明	避免长时间暴晒与潮湿环境，封面脏污可用软布轻轻擦拭，金属配件避免接触酸碱液体</p>', 1, '2025-10-15 11:30:12', '2025-10-15 11:30:12');

-- ----------------------------
-- Table structure for sys_file_info
-- ----------------------------
DROP TABLE IF EXISTS `sys_file_info`;
CREATE TABLE `sys_file_info`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '文件ID',
  `original_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '原始文件名',
  `file_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '文件访问路径',
  `file_size` bigint NOT NULL COMMENT '文件大小(字节)',
  `file_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '文件类型(IMG/PDF/TXT/AUDIO/VIDEO)',
  `business_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '业务类型',
  `business_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '业务对象ID(支持数字ID和UUID)',
  `business_field` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '业务字段名',
  `upload_user_id` bigint NULL DEFAULT NULL COMMENT '上传用户ID',
  `is_temp` tinyint(1) NULL DEFAULT 0 COMMENT '是否临时文件(0:否 1:是)',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态(0:删除 1:正常)',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `expire_time` datetime NULL DEFAULT NULL COMMENT '过期时间(临时文件)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_business`(`business_type` ASC, `business_id` ASC) USING BTREE,
  INDEX `idx_business_field`(`business_type` ASC, `business_id` ASC, `business_field` ASC) USING BTREE,
  INDEX `idx_upload_user`(`upload_user_id` ASC) USING BTREE,
  INDEX `idx_is_temp`(`is_temp` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_file_path`(`file_path` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 164 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '文件信息表-精简版' ROW_FORMAT = DYNAMIC;

